export const duration=34,cols=8,rows=6,total=48;
export const config={title:'超音波封裝檢測',sceneLabel:'水耦合脈衝回波逐列掃描，在同一深度時間窗累積C掃描影像',question:'回波逐點累積，形成界面訊號圖',overview:28.5,notes:['採水耦合脈衝回波C-SAM，聚焦並選取同一內部界面的時間窗。先用教學剖切指出一處既有分層，再恢復外觀；剖切不是檢測過程的物理切割。正常及分層兩個單點先示範回波，正式逐列掃描從14秒開始。','右側或下方C掃描只填入已接收時間窗回波的位置。蛇形掃描每個格點先發送、再接收，回波返回後才填格；深色表示本例所選時間窗內較大的回波幅值，淺色是正常參考。空白格代表未測，不代表正常。','含氣分層常造成強反射，但強或亮訊號也可能與材料界面、耦合及設定有關。本例與正常參考比較後圈出待判讀區，不把所有亮點判成缺陷。未模擬相位反轉，只用定性幅值編碼。','頻率、衰減與解析度互相制約；上方強反射可遮蔽深部，水耦合不良也影響訊號。圖是所選深度範圍的聲學訊號，並非透視照片；不保證能看穿任意材料。聲波放慢、缺陷與格點放大，不使用實測數值。','完成件帶原有分層離開；檢測沒有修補缺陷。結果卡表示本輪資料另存，下一輪清空量測區並使用新封裝編號。這是動畫中的資訊副本，重載網頁不保存實際檢測資料；沒有未要求的後端。'],sources:[['PVA TePla：脈衝回波、水耦合、逐列掃描與A/C-scan時間窗','https://www.pvatepla.com/products-technologies/advanced-packaging-inspection/']]};
export const steps=[{end:5,title:'入槽與既有分層',key:3.5,what:'封裝進入水耦合環境，教學剖切標出固定位置的既有分層。',detail:'隨後恢復完整外觀，檢測不會改變分層位置或修好它。'},{end:10,title:'正常界面回波',key:8.1,what:'探頭在正常位置發出脈衝，接收對應深度時間窗內的回波。',detail:'本段是單點示範，尚未填入正式C掃描。'},{end:14,title:'分層位置回波',key:13.1,what:'移到分層對應位置，同一時間窗接到較強反射。',detail:'幅值與正常參考不同，但不能把任意強訊號直接判成缺陷。'},{end:27,title:'逐列掃描成圖',key:21,what:'探頭沿蛇形路徑逐格量測，回波返回後才填入該座標。',detail:'圖中空白區仍未測，游標與探頭使用相同列行座標。'},{end:30,title:'判讀區與結果留存',key:29.3,what:'完整C掃描圈出與正常參考不同的區域，結果另存為卡片。',detail:'這是特定深度時間窗的聲學訊號圖；圈選區仍需判讀。'},{end:34,title:'原件退場與新件',key:31,what:'已測件帶著原有分層完整離開，資訊副本留在結果卡。',detail:'下一輪換新封裝與新圖，前輪結果卡仍保留到新結果取代它。'}];
export const ramp=(t,a,b)=>Math.max(0,Math.min(1,(t-a)/(b-a)));export const ease=x=>x*x*(3-2*x);export const isDefect=(col,row)=>col>=4&&col<=5&&row>=2&&row<=3;export function coord(i){const row=Math.floor(i/cols);return {row,col:row%2?cols-1-i%cols:i%cols};}
export function stateAt(t,cycle=0){t=Math.max(0,Math.min(duration-.0001,t));const index=steps.findIndex(s=>t<s.end),scan=ramp(t,14,27)*total,cell=Math.min(total-1,Math.floor(scan)),frac=scan-Math.floor(scan);let c=t<10?{col:1,row:1}:t<14?{col:5,row:3}:coord(cell),pulse=t<14?((Math.max(0,t-5)/1.7)%1):frac,count=t<14?0:t>=27?total:Math.floor(scan)+(frac>=.8?1:0);const prev=t<10?c:t<14?{col:1,row:1}:cell===0?{col:5,row:3}:coord(cell-1),move=t<10||t>=27?1:t<14?ease(ramp(t,10,10.7)):ease(ramp(frac,0,.18)),posCol=prev.col+(c.col-prev.col)*move,posRow=prev.row+(c.row-prev.row)*move;return {t,cycle,index,posCol,posRow,step:steps[index],entry:ease(ramp(t,0,1)),cut:1-ease(ramp(t,4,5)),...c,pulse,count,defect:isDefect(c.col,c.row),active:t>=5&&t<27&&move===1,gate:pulse>=.8,review:t>=27,saved:t>=29?cycle+1:cycle>0?cycle:0,exit:ease(ramp(t,31,33.5))};}
